-- Isolated synthetic integration test. The runner injects a schema-renamed copy
-- of drive_backup_v2017.sql at the marker. No real POS table is used.
BEGIN;
CREATE SCHEMA manara_v2017_test_public;
CREATE SCHEMA manara_v2017_test_private;
CREATE TABLE manara_v2017_test_public.customers(id uuid PRIMARY KEY,name text);
CREATE TABLE manara_v2017_test_public.products(id uuid PRIMARY KEY,name text,price numeric);
CREATE TABLE manara_v2017_test_public.transactions(id uuid PRIMARY KEY);
CREATE TABLE manara_v2017_test_public.transaction_items(id uuid PRIMARY KEY,transaction_id uuid);
CREATE TABLE manara_v2017_test_public.pos_settings(id integer PRIMARY KEY);
CREATE TABLE manara_v2017_test_public.pos_audit_log(id bigint PRIMARY KEY);
CREATE TABLE manara_v2017_test_public.pos_employee_audit(id bigint PRIMARY KEY);
CREATE TABLE manara_v2017_test_public.employees(user_id uuid PRIMARY KEY,display_name text,role text,active boolean,is_owner boolean,permissions jsonb,linked_customer_id uuid);
CREATE TABLE manara_v2017_test_public.pos_staff_logins(user_id uuid PRIMARY KEY,username text,owner_terminal boolean,removed_at timestamptz);
CREATE TABLE manara_v2017_test_public.pos_staff_sessions(session_id uuid PRIMARY KEY,user_id uuid,expires_at timestamptz,revoked_at timestamptz);
CREATE TABLE manara_v2017_test_public.pos_owner_grants(session_id uuid PRIMARY KEY,expires_at timestamptz);
CREATE TABLE manara_v2017_test_private.pos_backup_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reason text,snapshot jsonb,transaction_count int,item_count int);
CREATE FUNCTION manara_v2017_test_public.uid() RETURNS uuid LANGUAGE sql AS $$SELECT '22222222-2222-4222-8222-222222222222'::uuid$$;
CREATE FUNCTION manara_v2017_test_private.current_session_id() RETURNS uuid LANGUAGE sql AS $$SELECT '11111111-1111-4111-8111-111111111111'::uuid$$;
CREATE FUNCTION manara_v2017_test_private.is_owner() RETURNS boolean LANGUAGE sql AS $$SELECT current_setting('manara_test.owner',true)='yes'$$;
CREATE FUNCTION manara_v2017_test_public.pos_backup_restore_v0945(uuid,text,text) RETURNS jsonb LANGUAGE sql AS $$SELECT '{"restored":true,"mock":true}'::jsonb$$;
CREATE TEMP TABLE manara_v2017_checks(label text PRIMARY KEY) ON COMMIT DROP;
INSERT INTO manara_v2017_test_public.customers VALUES('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','DEMO');
INSERT INTO manara_v2017_test_public.products VALUES('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','DEMO',10);
INSERT INTO manara_v2017_test_public.transactions VALUES('cccccccc-cccc-4ccc-8ccc-cccccccccccc');
INSERT INTO manara_v2017_test_public.transaction_items VALUES('dddddddd-dddd-4ddd-8ddd-dddddddddddd','cccccccc-cccc-4ccc-8ccc-cccccccccccc');
INSERT INTO manara_v2017_test_public.pos_settings VALUES(1);
INSERT INTO manara_v2017_test_public.employees VALUES('22222222-2222-4222-8222-222222222222','DEMO owner terminal','staff',true,false,'{}',NULL),('44444444-4444-4444-8444-444444444444','DEMO staff','staff',true,false,'{"manage_system":true}',NULL);
INSERT INTO manara_v2017_test_public.pos_staff_logins VALUES('22222222-2222-4222-8222-222222222222','DEMO owner',true,NULL),('44444444-4444-4444-8444-444444444444','DEMO staff',false,NULL);
INSERT INTO manara_v2017_test_public.pos_staff_sessions VALUES('11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222',now()+interval '24 hours',NULL),('33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444',now()+interval '24 hours',NULL);
INSERT INTO manara_v2017_test_public.pos_owner_grants VALUES('11111111-1111-4111-8111-111111111111',now()+interval '24 hours');
-- __MIGRATION__
DO $test$
DECLARE os uuid:='11111111-1111-4111-8111-111111111111'; ou uuid:='22222222-2222-4222-8222-222222222222';
 ss uuid:='33333333-3333-4333-8333-333333333333'; su uuid:='44444444-4444-4444-8444-444444444444';
 s jsonb; o jsonb; j jsonb; b jsonb; sid uuid; id1 uuid; id2 uuid; proof uuid;
 blocked boolean; d timestamp; n integer; m integer; daynum integer; x integer;
BEGIN
 s:=manara_v2017_test_public.pos_drive_owner_v2017('status',os,ou,'{}');
 IF s->>'connected'<>'false' OR s#>>'{schedules,0,weekday}'<>'6' OR s#>>'{schedules,0,minute_of_day}'<>'420' OR s#>>'{schedules,0,kind}'<>'both' THEN RAISE EXCEPTION 'default'; END IF;
 INSERT INTO manara_v2017_checks VALUES('default Saturday 07:00 both');
 blocked:=false; BEGIN PERFORM manara_v2017_test_public.pos_drive_owner_v2017('status',ss,su,'{}'); EXCEPTION WHEN insufficient_privilege THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'staff allowed'; END IF;
 INSERT INTO manara_v2017_checks VALUES('limited staff denied');
 UPDATE manara_v2017_test_public.pos_owner_grants SET expires_at=now()-interval '1 second' WHERE session_id=os;
 blocked:=false; BEGIN PERFORM manara_v2017_test_public.pos_drive_owner_v2017('status',os,ou,'{}'); EXCEPTION WHEN insufficient_privilege THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'expired allowed'; END IF;
 UPDATE manara_v2017_test_public.pos_owner_grants SET expires_at=now()+interval '24 hours' WHERE session_id=os;
 INSERT INTO manara_v2017_checks VALUES('expired owner denied');
 UPDATE manara_v2017_test_public.pos_staff_sessions SET revoked_at=now() WHERE session_id=os;
 blocked:=false; BEGIN PERFORM manara_v2017_test_public.pos_drive_owner_v2017('status',os,ou,'{}'); EXCEPTION WHEN insufficient_privilege THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'revoked allowed'; END IF;
 UPDATE manara_v2017_test_public.pos_staff_sessions SET revoked_at=NULL WHERE session_id=os;
 INSERT INTO manara_v2017_checks VALUES('revoked session denied');
 IF has_function_privilege('authenticated','manara_v2017_test_public.pos_drive_owner_v2017(text,uuid,uuid,jsonb)','EXECUTE') OR has_function_privilege('anon','manara_v2017_test_public.pos_drive_worker_v2017(text,jsonb)','EXECUTE') OR NOT has_function_privilege('service_role','manara_v2017_test_public.pos_drive_worker_v2017(text,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'unsafe grants'; END IF;
 INSERT INTO manara_v2017_checks VALUES('service-only backup RPCs');
 id1:=(manara_v2017_test_public.pos_drive_owner_v2017('save_schedule',os,ou,'{"weekday":3,"minute_of_day":540,"kind":"data","enabled":true}')->>'id')::uuid;
 id2:=(manara_v2017_test_public.pos_drive_owner_v2017('save_schedule',os,ou,'{"weekday":3,"minute_of_day":660,"kind":"both","enabled":true}')->>'id')::uuid;
 IF id1=id2 OR (SELECT count(*) FROM manara_v2017_test_private.drive_backup_schedules)<>3 THEN RAISE EXCEPTION 'add schedules'; END IF;
 INSERT INTO manara_v2017_checks VALUES('multiple weekly slots on same day');
 blocked:=false; BEGIN PERFORM manara_v2017_test_public.pos_drive_owner_v2017('save_schedule',os,ou,'{"weekday":3,"minute_of_day":540,"kind":"both","enabled":true}'); EXCEPTION WHEN unique_violation THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'duplicate'; END IF;
 INSERT INTO manara_v2017_checks VALUES('duplicate slot rejected');
 PERFORM manara_v2017_test_public.pos_drive_owner_v2017('save_schedule',os,ou,jsonb_build_object('id',id1,'weekday',4,'minute_of_day',600,'kind','data','enabled',false));
 IF NOT EXISTS(SELECT 1 FROM manara_v2017_test_private.drive_backup_schedules WHERE id=id1 AND weekday=4 AND minute_of_day=600 AND NOT enabled) THEN RAISE EXCEPTION 'edit'; END IF;
 PERFORM manara_v2017_test_public.pos_drive_owner_v2017('delete_schedule',os,ou,jsonb_build_object('id',id2));
 IF EXISTS(SELECT 1 FROM manara_v2017_test_private.drive_backup_schedules WHERE id=id2) THEN RAISE EXCEPTION 'delete'; END IF;
 INSERT INTO manara_v2017_checks VALUES('edit disable and delete slot');
 blocked:=false; BEGIN PERFORM manara_v2017_test_public.pos_drive_owner_v2017('enable',os,ou,'{"enabled":true}'); EXCEPTION WHEN OTHERS THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'enable disconnected'; END IF;
 INSERT INTO manara_v2017_checks VALUES('cannot enable disconnected');
 PERFORM manara_v2017_test_public.pos_drive_owner_v2017('oauth_start',os,ou,jsonb_build_object('stateHash',repeat('a',64),'verifier','DEMO'));
 o:=manara_v2017_test_public.pos_drive_oauth_v2017('consume',jsonb_build_object('stateHash',repeat('a',64)));
 IF o->>'session_id'<>os::text OR o->>'user_id'<>ou::text THEN RAISE EXCEPTION 'oauth binding'; END IF;
 blocked:=false; BEGIN PERFORM manara_v2017_test_public.pos_drive_oauth_v2017('consume',jsonb_build_object('stateHash',repeat('a',64))); EXCEPTION WHEN OTHERS THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'state reused'; END IF;
 INSERT INTO manara_v2017_checks VALUES('OAuth state bound and single use');
 PERFORM manara_v2017_test_public.pos_drive_oauth_v2017('finish',jsonb_build_object('session_id',os,'user_id',ou,'generation',o->>'generation','encryptedToken','DEMO_ONLY','rootFolder','demo-root','dataFolder','demo-data','systemFolder','demo-system'));
 s:=manara_v2017_test_public.pos_drive_owner_v2017('status',os,ou,'{}');
 IF s->>'connected'<>'true' OR s::text LIKE '%DEMO_ONLY%' OR s->>'enabled'<>'false' THEN RAISE EXCEPTION 'connection exposure'; END IF;
 INSERT INTO manara_v2017_checks VALUES('connection private and disabled until enable');
 blocked:=false; BEGIN PERFORM manara_v2017_test_public.pos_drive_owner_v2017('enable',os,ou,'{"enabled":true}'); EXCEPTION WHEN OTHERS THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'system not ready'; END IF;
 INSERT INTO manara_v2017_checks VALUES('system package required for both schedule');
 PERFORM manara_v2017_test_public.pos_drive_worker_v2017('register_release',jsonb_build_object('version','2.0.16','commit_sha',repeat('a',40),'storage_path','2.0.16/'||repeat('a',40)||'.zip','sha256',repeat('b',64),'byte_size',1024));
 PERFORM manara_v2017_test_public.pos_drive_owner_v2017('enable',os,ou,'{"enabled":true}');
 UPDATE manara_v2017_test_private.drive_backup_connection SET enabled_since=now()-interval '24 hours' WHERE id=1;
 UPDATE manara_v2017_test_private.drive_backup_schedules SET enabled=false;
 d:=now() AT TIME ZONE 'Asia/Jerusalem';daynum:=extract(dow FROM d)::int;
 m:=floor((extract(hour FROM d)*60+extract(minute FROM d))/15)::int*15;
 INSERT INTO manara_v2017_test_private.drive_backup_schedules(weekday,minute_of_day,kind,enabled,updated_at)
 VALUES(daynum,m,'both',true,now()-interval '24 hours') ON CONFLICT(weekday,minute_of_day) DO UPDATE SET kind='both',enabled=true,updated_at=excluded.updated_at;
 d:=d-interval '15 minutes';daynum:=extract(dow FROM d)::int;m:=floor((extract(hour FROM d)*60+extract(minute FROM d))/15)::int*15;
 INSERT INTO manara_v2017_test_private.drive_backup_schedules(weekday,minute_of_day,kind,enabled,updated_at)
 VALUES(daynum,m,'data',true,now()-interval '24 hours') ON CONFLICT(weekday,minute_of_day) DO UPDATE SET kind='data',enabled=true,updated_at=excluded.updated_at;
 n:=manara_v2017_test_private.drive_backup_tick();x:=manara_v2017_test_private.drive_backup_tick();
 IF n<>2 OR x<>0 THEN RAISE EXCEPTION 'scheduler counts % %',n,x; END IF;
 INSERT INTO manara_v2017_checks VALUES('local-time due slots and repeat tick deduplication');
 UPDATE manara_v2017_test_private.drive_backup_jobs SET next_at=now()-interval '1 minute' WHERE kind='both';
 j:=(manara_v2017_test_public.pos_drive_worker_v2017('claim','{}')->'job');
 IF j->>'kind'<>'both' OR j->>'attempts'<>'1' OR jsonb_array_length((j->>'snapshot_text')::jsonb->'transactions')<>1 THEN RAISE EXCEPTION 'claim'; END IF;
 INSERT INTO manara_v2017_checks VALUES('snapshot and leased claim');
 b:=jsonb_build_object('id',j->>'id','lease',j->>'lease');
 blocked:=false; BEGIN PERFORM manara_v2017_test_public.pos_drive_worker_v2017('complete',b); EXCEPTION WHEN OTHERS THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'unverified complete'; END IF;
 PERFORM manara_v2017_test_public.pos_drive_worker_v2017('reserve',b||'{"kind":"data","fileId":"demo-data-file"}');
 PERFORM manara_v2017_test_public.pos_drive_worker_v2017('verified',b||jsonb_build_object('kind','data','fileId','demo-data-file','sha256',repeat('c',64)));
 blocked:=false; BEGIN PERFORM manara_v2017_test_public.pos_drive_worker_v2017('complete',b); EXCEPTION WHEN OTHERS THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'partial completed'; END IF;
 PERFORM manara_v2017_test_public.pos_drive_worker_v2017('reserve',b||'{"kind":"system","fileId":"demo-system-file"}');
 PERFORM manara_v2017_test_public.pos_drive_worker_v2017('verified',b||jsonb_build_object('kind','system','fileId','demo-system-file','sha256',repeat('d',64)));
 PERFORM manara_v2017_test_public.pos_drive_worker_v2017('complete',b);
 IF NOT EXISTS(SELECT 1 FROM manara_v2017_test_private.drive_backup_jobs WHERE id=(j->>'id')::uuid AND status='succeeded' AND snapshot_text IS NULL) THEN RAISE EXCEPTION 'success'; END IF;
 INSERT INTO manara_v2017_checks VALUES('both files must verify before success');
 FOR n IN 1..3 LOOP
  j:=(manara_v2017_test_public.pos_drive_worker_v2017('claim','{}')->'job');
  IF j->>'kind'<>'data' OR (j->>'attempts')::int<>n THEN RAISE EXCEPTION 'retry claim %',n; END IF;
  b:=jsonb_build_object('id',j->>'id','lease',j->>'lease','errorCode','test_failure');
  PERFORM manara_v2017_test_public.pos_drive_worker_v2017('fail',b);
  IF n=1 AND NOT EXISTS(SELECT 1 FROM manara_v2017_test_private.drive_backup_jobs WHERE id=(j->>'id')::uuid AND status='retry' AND next_at=now()+interval '15 minutes') THEN RAISE EXCEPTION 'retry15'; END IF;
  IF n=2 AND NOT EXISTS(SELECT 1 FROM manara_v2017_test_private.drive_backup_jobs WHERE id=(j->>'id')::uuid AND status='retry' AND next_at=now()+interval '1 hour') THEN RAISE EXCEPTION 'retry60'; END IF;
  IF n=3 AND NOT EXISTS(SELECT 1 FROM manara_v2017_test_private.drive_backup_jobs WHERE id=(j->>'id')::uuid AND status='failed') THEN RAISE EXCEPTION 'retry terminal'; END IF;
  UPDATE manara_v2017_test_private.drive_backup_jobs SET next_at=now()-interval '1 second' WHERE id=(j->>'id')::uuid;
 END LOOP;
 INSERT INTO manara_v2017_checks VALUES('retry 15m 60m and final failure');
 s:=manara_v2017_test_public.pos_drive_owner_v2017('manual',os,ou,'{"kind":"data","requestId":"55555555-5555-4555-8555-555555555555"}');
 o:=manara_v2017_test_public.pos_drive_owner_v2017('manual',os,ou,'{"kind":"data","requestId":"55555555-5555-4555-8555-555555555555"}');
 IF s->>'id'<>o->>'id' THEN RAISE EXCEPTION 'manual duplicate'; END IF;
 INSERT INTO manara_v2017_checks VALUES('manual request idempotent');
 sid:=(manara_v2017_test_public.pos_drive_owner_v2017('import_verified',os,ou,jsonb_build_object('snapshot',manara_v2017_test_private.drive_snapshot()::jsonb))->>'snapshotId')::uuid;
 PERFORM set_config('manara_test.owner','yes',true);
 blocked:=false; BEGIN PERFORM manara_v2017_test_public.pos_backup_restore_v2017(sid,repeat('e',32),'אני מאשר שחזור מלא',gen_random_uuid()); EXCEPTION WHEN insufficient_privilege THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'restore without proof'; END IF;
 proof:=(manara_v2017_test_public.pos_drive_owner_v2017('proof',os,ou,jsonb_build_object('snapshotId',sid,'checksum',repeat('e',32)))->>'proof')::uuid;
 s:=manara_v2017_test_public.pos_backup_restore_v2017(sid,repeat('e',32),'אני מאשר שחזור מלא',proof);
 IF s->>'mock'<>'true' THEN RAISE EXCEPTION 'restore wrapper'; END IF;
 blocked:=false; BEGIN PERFORM manara_v2017_test_public.pos_backup_restore_v2017(sid,repeat('e',32),'אני מאשר שחזור מלא',proof); EXCEPTION WHEN insufficient_privilege THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'proof reused'; END IF;
 INSERT INTO manara_v2017_checks VALUES('fresh restore proof single use');
 IF has_function_privilege('authenticated','manara_v2017_test_private.pos_backup_restore_v0945(uuid,text,text)','EXECUTE') THEN RAISE EXCEPTION 'legacy bypass'; END IF;
 INSERT INTO manara_v2017_checks VALUES('legacy restore RPC direct execution revoked');
 PERFORM manara_v2017_test_public.pos_drive_owner_v2017('disconnect',os,ou,'{}');
 s:=manara_v2017_test_public.pos_drive_owner_v2017('status',os,ou,'{}');
 IF s->>'connected'<>'false' OR s->>'enabled'<>'false' OR manara_v2017_test_private.drive_backup_tick()<>0 THEN RAISE EXCEPTION 'disconnect'; END IF;
 INSERT INTO manara_v2017_checks VALUES('disconnect stops future backups');
END $test$;
SELECT count(*) AS passed,jsonb_agg(label ORDER BY label) AS checks FROM manara_v2017_checks;
ROLLBACK;
